type Stmt =
    | { kind: "assign"; name: string; value: number }
    | { kind: "call"; name: string }
    | { kind: "return"; name: string };

let total = 0;
let observed = 0;

function report(): void {
    observed = total;
}

function optimize(body: Stmt[]): Stmt[] {
    return body.filter(function dropOverwritten(stmt, index) {
        if (stmt.kind !== "assign") {
            return true;
        }
        return !body.slice(index + 1).some(function laterStore(next) {
            return next.kind === "assign" && next.name === stmt.name;
        });
    });
}

function execute(body: Stmt[]): number {
    for (const stmt of body) {
        if (stmt.kind === "assign") {
            total = stmt.value;
        } else if (stmt.kind === "call") {
            report();
        } else {
            return observed;
        }
    }
    return observed;
}

const before: Stmt[] = [
    { kind: "assign", name: "total", value: 1 },
    { kind: "call", name: "report" },
    { kind: "assign", name: "total", value: 2 },
    { kind: "return", name: "observed" },
];

execute(before);
execute(optimize(before));
